    &lt;GridButtonGroups&gt;[]&lt;/GridButtonGroups&gt;
    &lt;ItemButtons&gt;[{&quot;ItemActions&quot;:[{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;334b4789-e73a-4925-bffa-b30df4655965&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;OpenAFPopup&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;ModuleId&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;a42c73da-edb9-4e4b-ac0e-5a722dad0eee&quot;},&quot;ReinitForm&quot;:true,&quot;Params&quot;:[{&quot;name&quot;:&quot;GarantiiRetrageriId&quot;,&quot;value&quot;:&quot;[Id]&quot;}],&quot;AllowUserClose&quot;:true,&quot;CloseOnClick&quot;:true,&quot;CloseOnEscape&quot;:true},&quot;Metadata&quot;:{&quot;PAP_InternalIdentifier&quot;:&quot;Button.Edit.OpenForm&quot;},&quot;HasActionParameters&quot;:true}}],&quot;OnItemClickActionStackId&quot;:-1,&quot;Url&quot;:&quot;&amp;amp;buttonName=Edit&quot;,&quot;ModuleId&quot;:1137,&quot;AutoName&quot;:false,&quot;Name&quot;:&quot;Edit&quot;,&quot;Title&quot;:&quot;&quot;,&quot;Help&quot;:&quot;Edit&quot;,&quot;ShowCondition&quot;:&quot;([HasRole:Admins] || [HasRole:CitizenDevelopers] || [HasRole:Low-CodeEngineer] || [HasRole:Managers])&quot;,&quot;IsEnabled&quot;:false,&quot;Metadata&quot;:{&quot;PAP_InternalIdentifier&quot;:&quot;Button.Edit&quot;},&quot;Type&quot;:&quot;ItemButton&quot;,&quot;OrderIndex&quot;:0,&quot;CssClass&quot;:&quot;default&quot;,&quot;CustomCssClass&quot;:null,&quot;IconClass&quot;:&quot;&quot;,&quot;FaIconClass&quot;:&quot;fas fa-pen&quot;,&quot;PermissionAllUsers&quot;:false,&quot;PermissionsExportJson&quot;:&quot;[\&quot;Admins\&quot;,\&quot;Citizen Developers\&quot;,\&quot;Low-Code Engineer\&quot;,\&quot;Managers\&quot;]&quot;,&quot;Permissions&quot;:[6,7,5,8],&quot;AskForConfirmation&quot;:false,&quot;ConfirmationMessage&quot;:null,&quot;ConfirmationOk&quot;:null,&quot;ConfirmationCancel&quot;:null,&quot;JsCode&quot;:null,&quot;IsClientButton&quot;:false,&quot;ButtonGroupId&quot;:null,&quot;ButtonGroupName&quot;:null,&quot;Id&quot;:0,&quot;EnableCondition&quot;:null,&quot;IsDeleted&quot;:false},{&quot;ItemActions&quot;:[{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;607d9014-9495-489d-ad69-015fef314ffb&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;ApplyTokens&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;Tokens&quot;:[{&quot;value&quot;:&quot;[Marca]&quot;,&quot;name&quot;:&quot;DelMarca&quot;}],&quot;TokenizeTokenNames&quot;:false,&quot;RecursionCount&quot;:&quot;1&quot;},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}},{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;4bff373d-9206-41af-bfe9-0c6991c605ff&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;PlantAnApp.DeleteEntity.e104afb9-e0ee-4733-a5c1-c0834cd02ee7&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:1,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;RecordId&quot;:&quot;[Id]&quot;,&quot;ConnectionString&quot;:null,&quot;OnError&quot;:[]},&quot;Metadata&quot;:{&quot;PAP_InternalIdentifier&quot;:&quot;Button.Delete.DeleteEntity&quot;,&quot;EntityIdentifier&quot;:&quot;e104afb9-e0ee-4733-a5c1-c0834cd02ee7&quot;,&quot;IsUidEnabled&quot;:&quot;True&quot;},&quot;HasActionParameters&quot;:true}},{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;e74eed71-1ab5-4ff5-ae43-81ab032b4836&quot;,&quot;Description&quot;:&quot;Actualizare Suma Retrasa in Garantii Materiale&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:2,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;UseTransactions&quot;:true,&quot;SqlQuery&quot;:&quot;;WITH TotalRetrageri AS (\n    SELECT\n        CAST(\n            ISNULL(SUM(ISNULL(gr.SumaRetrasa, 0)), 0)\n            AS DECIMAL(18, 2)\n        ) AS SumaRetrasaTotal\n    FROM app.GarantiiRetrageri gr\n    WHERE gr.Marca = @Marca\n      AND gr.CodSucursala = @CodSucursala\n      AND gr.Anul = @Anul\n      AND gr.Luna = @Luna\n)\nUPDATE gm\nSET\n    gm.SumaTotala =\n        CAST(\n            ISNULL(gm.SumaTotala, 0)\n            -\n            (\n                ISNULL(t.SumaRetrasaTotal, 0)\n                -\n                ISNULL(gm.SumaRetrasa, 0)\n            )\n            AS DECIMAL(18, 2)\n        ),\n\n    gm.SumaRetrasa =\n        CAST(ISNULL(t.SumaRetrasaTotal, 0) AS DECIMAL(18, 2)),\n\n    gm.LastModifiedDate = SYSDATETIMEOFFSET()\n\nFROM app.GarantieMateriala gm\nCROSS JOIN TotalRetrageri t\nWHERE gm.Marca = @Marca\n  AND gm.CodSucursala = @CodSucursala\n  AND gm.Anul = @Anul\n  AND gm.Luna = @Luna;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[DelMarca]&quot;,&quot;name&quot;:&quot;Marca&quot;},{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quo